// Valideer periode-parameter: mag alleen JJJJ-MM formaat zijn
const raw = String($input.first().json.query?.periode || '');
const isValid = /^\d{4}-\d{2}$/.test(raw);
if (!isValid) {
  throw new Error(`Ongeldig periode-formaat: '${raw}'. Verwacht formaat: JJJJ-MM (bijv. 2026-05)`);
}
// Bereken begin- en einddatum voor de maand (veiliger dan LIKE)
const [year, month] = raw.split('-').map(Number);
const startDate = `${String(year).padStart(4,'0')}-${String(month).padStart(2,'0')}-01`;
const nextMonth = month === 12 ? 1 : month + 1;
const nextYear = month === 12 ? year + 1 : year;
const endDate = `${String(nextYear).padStart(4,'0')}-${String(nextMonth).padStart(2,'0')}-01`;
return [{ json: { periode: raw, start_date: startDate, end_date: endDate } }];

const omzetData = $('SQLite: Omzet ophalen').first().json;
const kostenData = $('SQLite: Kosten ophalen').first().json;
const btwData = $('SQLite: BTW ophalen').first().json;
const validated = $('Function: Periode valideren').first().json;

const omzet = Math.round(parseFloat(omzetData.omzet || 0) * 100) / 100;
const kosten = Math.round(parseFloat(kostenData.kosten || 0) * 100) / 100;
const btwTeBetalen = Math.round(parseFloat(btwData.btw_te_betalen || 0) * 100) / 100;
const winst = Math.round((omzet - kosten) * 100) / 100;

return [{ json: { periode: validated.periode, omzet, kosten, winst, btw_te_betalen: btwTeBetalen } }];
